//! 🧪️ Entity-only SELECTs use exact original References and complete source membership.
use super::*;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-reference-select-input.json")).unwrap()}
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"derived"=>IfcValue::Derived,"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"enum"=>IfcValue::Enum(row["value"].as_str().unwrap().into()),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed source fixture")}}
fn source(law:&serde_json::Value,name:&str)->Arc<IfcSnapshot>{Arc::new(IfcSnapshot{entities:law["sources"][name]["entities"].as_array().unwrap().iter().map(|row|IfcEntity{id:row["id"].as_str().unwrap().parse().unwrap(),name:row["name"].as_str().unwrap().into(),args:row["args"].as_array().unwrap().iter().map(value).collect(),complex:row["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(value).collect()}).collect()}).collect(),..Default::default()})}
fn event(law:&serde_json::Value,row:&serde_json::Value)->editing::SnapshotEditEvent{let domain=law["domains"].as_array().unwrap().iter().find(|domain|domain["source"]==row["source"]).unwrap();editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":domain["entity"],"$ifcInputs":[{"index":domain["index"],"value":{"kind":"reference","value":row["reference"]}}]}))}}
#[test]
fn original_entity_select_kind_inspects_all_released_members_without_a_typed_entity_wrapper(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for domain in law["domains"].as_array().unwrap(){let attribute=DetailsTestProfile::normalization_attribute(domain["entity"].as_str().unwrap(),domain["index"].as_str().unwrap().parse().unwrap(),true).unwrap().unwrap();let mut cursor=super::super::super::type_input_kind::Cursor::default();let mut complete=None;for turn in 0..1024{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>(attribute.type_expr));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(kind)=answer.unwrap(){complete=Some(kind);assert!(turn>=domain["members"].as_array().unwrap().len());break;}}assert_eq!(complete,Some(super::super::super::type_input_kind::Kind::Reference));assert_eq!(cursor.domain(),domain["select"].as_str());}
}
#[test]
fn original_entity_selects_use_actual_source_subtypes_strict_candidate_and_exact_inverse(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law,row["source"].as_str().unwrap());let domain=law["domains"].as_array().unwrap().iter().find(|domain|domain["source"]==row["source"]).unwrap();let index=domain["index"].as_str().unwrap().parse::<usize>().unwrap();let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(&law,row),&mut caller,&mut work,|input,caller,work|{let mut result=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{result=Some(Ok(emit));break;},Err(error)=>{result=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let result=result.unwrap();assert_eq!(result.is_ok(),row["admitted"].as_bool().unwrap(),"{}",row["id"]);if let Ok(emit)=result{assert_eq!(emit.artifact_mutations.len(),1);assert!(matches!(emit.artifact_mutations[0],IfcMutation::SetEntityArg(_)));let mutation=&emit.artifact_mutations[0];let inverse=mutation.inverse(&snapshot).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&snapshot).diff(),&snapshot).unwrap();assert!(matches!(next.entities[0].args[index],IfcValue::Reference(id)if id==row["reference"].as_str().unwrap().parse::<u64>().unwrap()));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));}super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();}
}
#[test]
fn original_reference_select_guidance_keeps_missing_and_partial_ids_editable_under_denied_axes(){
 use semio_framework_plugin::action_staging::*;use semio_framework_plugin_decl_staged_form::*;
 type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){for supplied in [false,true]{let snapshot=source(&law,row["source"].as_str().unwrap());let editing::SnapshotEditEvent::SetValue{path,mut value}=event(&law,row)else{unreachable!()};if !supplied{let DslValue::Object(fields)=&mut value else{unreachable!()};fields.iter_mut().find(|(key,_)|key=="$ifcInputs").unwrap().1=DslValue::Array(Vec::new());}let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"reference-select-original".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:None});let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();let(repeated,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||guide.as_ref().unwrap().demands());assert_eq!(repeated.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert_eq!(prepared.status().ready,supplied&&row["admitted"].as_bool().unwrap());assert_eq!(prepared.controls(),1);let control=prepared.control(0).unwrap();let StagedScalarKind::Text{value}=control.scalar.kind else{panic!("source-classified exact reference")};assert_eq!(value,if supplied{row["reference"].as_str().unwrap()}else{""});let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("original reference binding")};let raw=DslValue::String(row["reference"].as_str().unwrap().into());assert!(binding.plan(prepared.status(),Some(&raw)).is_ok());caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();}}
}
